async ({ workspace: { read, edit }, shell: { execFile } }) => {
  const r = await read("CHANGELOG.md", { format: "raw" });
  const next = r.content.replace(/<<<<<<< HEAD\n([\s\S]*?)=======\n([\s\S]*?)>>>>>>> [^\n]*\n/, (_, head: string, mine: string) => `${mine}\n${head}`);
  if (next.includes("<<<<<<<")) throw new Error("unresolved");
  await edit("CHANGELOG.md", { revision: r.revision, changes: [{ kind: "replaceFile", content: next }] });
  await execFile("git", ["add", "CHANGELOG.md"], { raise: true });
  const c = await execFile("git", ["-c", "core.editor=true", "rebase", "--continue"]);
  const s = (await read("CHANGELOG.md", { format: "raw", offset: 5, limit: 14 })).content;
  return { c: c.stdout + c.stderr + c.code, s };
}
